    'web.challenge.f.email.help': 'Адрес, который организаторы используют, если им нужно связаться с вами по поводу вашей заявки. Предварительно заполнен адрес электронной почты вашей учетной записи — измените его, если лучше использовать другой почтовый ящик.',
    'web.challenge.f.account.label': 'Аккаунт Manyfold',
