    'web.landing.kicker': 'Платформа хостинга агентов',
    'web.landing.heroBody': 'Создавайте и размещайте агенты Claude Code, Codex и платформы в одном облачном рабочем пространстве.',
    'web.landing.agentsKicker': 'Агенты',
    'web.landing.agentsTitle': 'Возьмите с собой агента, который уже использует ваша команда.',
    'web.landing.agentsBody': 'Начните с собственных агентов кодирования, а затем добавляйте агенты платформы, когда рабочим процессам потребуются службы, планировщики или соединители.',
    'web.landing.claudeCodeBody': 'Собственная рабочая область кодирования для задач репозитория и длительных сеансов разработки.',
