    'web.landing.statefulSandboxBody': 'Надежное изолированное рабочее пространство для агентов кодирования с файлами, состоянием терминала и контекстом сеанса, готовым к возобновлению.',
    'web.landing.persistentRuntimeBody': 'Облачный компьютер для агентов, которым необходимы постоянные службы, запланированная работа или соединители платформы.',
    'web.landing.navAgents': 'Агенты',
    'web.landing.navRuntime': 'Среда выполнения',
    'web.landing.navPricing': 'Цены',
    'web.landing.navDocs': 'Документы',
    'web.landing.navChallenge': 'Испытание',
    'web.landing.themeToggle': 'Переключить тему',
    'web.landing.heroTitle1': 'Одно рабочее пространство',
    'web.landing.heroTitle2': 'для всех агентов,',
    'web.landing.heroTitle3': 'с которыми вы работаете.',
    'web.landing.heroSubtitle': 'Создавайте и размещайте агенты Claude Code, Codex и платформы в одном облачном рабочем пространстве. Изолированная, возобновляемая и тихая по своей конструкции.',
    'web.landing.heroPrimaryCta': 'Создайте своего первого агента',
    'web.landing.hostsLabel': 'Хозяева',
    'web.landing.howKicker': 'Как это работает',
    'web.landing.howTitle': 'Три шага к работающему агенту.',
    'web.landing.howBody': 'Выберите среду выполнения, при необходимости подключите провайдера, а затем начните работать в рабочей области чата. Нет инфраструктуры для присмотра за детьми.',
    'web.landing.howStep1Title': 'Выберите среду выполнения',
    'web.landing.howStep1Body': 'Песочница с сохранением состояния для задач кодирования, облачный компьютер для постоянно работающих сервисов.',
    'web.landing.howStep2Title': 'Подключить провайдера',
    'web.landing.howStep2Body': 'Anthropic, OpenAI, Google или ваши собственные ключи. Маршрутизируется для каждого агента.',
    'web.landing.howStep3Title': 'Начать работать',
    'web.landing.howStep3Body': 'Откройте рабочую область чата и введите команды. Сеансы возобновляются с того места, на котором вы остановились.',
    'web.landing.faqKicker': 'Часто задаваемые вопросы',
    'web.landing.faqTitle': 'Вопросы, ответы понятные.',
    'web.landing.faqQ1': 'Это очередная обертка Claude/Codex?',
    'web.landing.faqA1': 'Нет. Manyfold размещает реальные среды выполнения агентов — Claude Code, Codex, Gemini CLI — в изолированных рабочих областях с прикрепленными файлами, состоянием терминала и возобновляемыми сеансами. Вы приносите ключи своего провайдера; мы запускаем цикл.',
    'web.landing.faqQ2': 'В чем разница между песочницей и облачным компьютером?',
    'web.landing.faqA2': 'Песочницы долговечны, но доступны по требованию: идеально подходят для задач репозитория, когда агенту нужны файлы, терминал и сеанс, который вы можете продолжить позже. Облачные компьютеры остаются в сети для выполнения заданий cron, соединителей и служб, которые никогда не должны переходить в режим сна.',
    'web.landing.faqQ3': 'Нужно ли мне иметь при себе ключи от своего провайдера?',
    'web.landing.faqA3': 'Можете. Ключи хранятся для каждой рабочей области и маршрутизируются для каждого агента — Claude Code на Anthropic, задание Codex на OpenAI, сеанс Gemini CLI на Google. Или используйте наш лимитированный доступ для любого из них.',
    'web.landing.faqQ4': 'Могу ли я использовать свой собственный агент платформы?',
    'web.landing.faqA4': 'Да. OpenClaw и Hermes являются первоклассными, и любая платформа, работающая в Linux + имеющая точку входа CLI, может быть размещена как пользовательское определение агента.',
    'web.landing.faqQ5': 'Как работает ценообразование?',
    'web.landing.faqA5': 'Фиксированная плата за рабочее пространство покрывает рельс, сеансы и одну песочницу с отслеживанием состояния. Облачные компьютеры и токены провайдера измеряются. Нет налога за место.',
    'web.landing.footerLegal': '© 2026 Manyfold',
